import * as T from './vendor/three.js';
import {facadeProfile,hash} from './appearance.js';
// Suggested yard envelopes derived from building footprints, not surveyed legal parcels.
export function propertyFencePlan(building,network){
 const profile=building.profile||facadeProfile(building);if(profile.shop||profile.industrial||profile.area<50||profile.area>500)return[];
 const hit=network.at(profile.x,profile.z);if(!hit||hit.r.bridge||!['residential','unclassified','tertiary','secondary','living_street'].includes(hit.r.type)||hit.d>45)return[];
 const a=hit.r.p[hit.i],b=hit.r.p[hit.i+1],length=a.distanceTo(b)||1,ux=(b.x-a.x)/length,uz=(b.y-a.y)/length;let vx=-uz,vz=ux;if((profile.x-a.x)*vx+(profile.z-a.y)*vz<0){vx=-vx;vz=-vz}
 const points=building.rings[0].map(([x,z])=>({u:(x-a.x)*ux+(z-a.y)*uz,v:(x-a.x)*vx+(z-a.y)*vz})),minU=Math.min(...points.map(p=>p.u))-2,maxU=Math.max(...points.map(p=>p.u))+2,minV=Math.max(hit.r.width/2+2,Math.min(...points.map(p=>p.v))-3),maxV=Math.max(...points.map(p=>p.v))+4;
 if(minV>=Math.min(...points.map(p=>p.v))-.7||maxU-minU>45||maxV-minV>45)return[];
 const world=(u,v)=>({x:a.x+ux*u+vx*v,z:a.y+uz*u+vz*v}),segments=[],add=(u0,v0,u1,v1,height)=>segments.push({a:world(u0,v0),b:world(u1,v1),height,id:building.id});
 // Four-metre driveway plus a separate one-metre pedestrian opening on the street edge.
 const driveway=hash(building.id)%2?minU+2.5:maxU-2.5,door=(minU+maxU)/2,openings=[[driveway-2,driveway+2],[door-.6,door+.6]].sort((a,b)=>a[0]-b[0]);let cursor=minU;for(const[start,end]of openings){if(start>cursor)add(cursor,minV,Math.min(start,maxU),minV,.95);cursor=Math.max(cursor,end)}if(cursor<maxU)add(cursor,minV,maxU,minV,.95);
 add(minU,minV,minU,maxV,1.65);add(maxU,minV,maxU,maxV,1.65);add(minU,maxV,maxU,maxV,1.65);return segments;
}
export function createPropertyFences(scene,{network,ground,hydro,coast,openSpaces,clear,budgetMs=2}){
 let timber=null;if(typeof document!=='undefined'){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');ctx.fillStyle='#e5e0d4';ctx.fillRect(0,0,256,256);for(let x=0;x<256;x+=20){ctx.fillStyle='#686154';ctx.fillRect(x,0,1,256);ctx.fillStyle='#fff9eb';ctx.fillRect(x+1,0,1,256)}for(let i=0;i<500;i++){ctx.fillStyle=i%2?'#4b423014':'#ffffff24';ctx.fillRect(i*71%256,i*43%256,1,5+i%30)}timber=new T.CanvasTexture(canvas);timber.colorSpace=T.SRGBColorSpace;timber.magFilter=T.LinearFilter;timber.anisotropy=4}
 const chunks=new Map(),collision=new Map(),geometry=new T.BoxGeometry(1,1,1),material=new T.MeshLambertMaterial({map:timber,color:'#ffffff'}),dummy=new T.Object3D(),color=new T.Color();let job=null,queue=[],next=0;
 function* build(c){const panels=[],posts=[],rails=[],segments=[];for(const b of c.buildings){for(const fence of propertyFencePlan(b,network)){const dx=fence.b.x-fence.a.x,dz=fence.b.z-fence.a.z,len=Math.hypot(dx,dz),steps=Math.ceil(len/1.8);let valid=true;for(let i=0;i<=Math.ceil(len);i++){const t=i/Math.ceil(len),x=fence.a.x+dx*t,z=fence.a.z+dz*t,road=network.at(x,z);if(network.junctionAt?.(x,z)||!clear(x,z)||!coast.isLand(x,z)||hydro.nearChannel(x,z,.7)||!openSpaces.allows(x,z,.2)||(road&&road.d<road.r.width/2+1.5)){valid=false;break}}if(!valid)continue;
 const shade=fence.height<1?'#d8d6c6':['#8f826b','#a59a80','#727e6d'][hash(b.id)%3],yaw=Math.atan2(dx,dz);
 for(let i=0;i<steps;i++){const t0=i/steps,t1=(i+1)/steps,x=fence.a.x+dx*(t0+t1)/2,z=fence.a.z+dz*(t0+t1)/2,y=ground(x,z);panels.push({x,y:y+fence.height/2,z,sx:.075,sy:fence.height,sz:len/steps-.025,yaw,color:shade});for(let rail=0;rail<2;rail++)rails.push({x:x+Math.cos(yaw)*.05,y:y+fence.height*(rail?.78:.27),z:z-Math.sin(yaw)*.05,sx:.065,sy:.08,sz:len/steps,yaw,color:'#6f6959'});posts.push({x:fence.a.x+dx*t0,y:ground(fence.a.x+dx*t0,fence.a.z+dz*t0)+(fence.height+.08)/2,z:fence.a.z+dz*t0,sx:.11,sy:fence.height+.08,sz:.11,yaw,color:shade})}segments.push(fence)}yield;}
 if(chunks.get(c.id)!==c)return;
 // Panels first, then posts, then rails, so distant chunks can draw just the leading panels.
 const parts=[...panels,...posts,...rails];c.panels=panels.length;const mesh=new T.InstancedMesh(geometry,material,parts.length);for(let i=0;i<parts.length;i++){const p=parts[i];dummy.position.set(p.x,p.y,p.z);dummy.scale.set(p.sx,p.sy,p.sz);dummy.rotation.set(0,p.yaw,0);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);mesh.setColorAt(i,color.set(p.color))}mesh.computeBoundingSphere();mesh.name='Property fences '+c.id;scene.add(mesh);c.mesh=mesh;c.segments=segments;for(const segment of segments){for(let ix=Math.floor((Math.min(segment.a.x,segment.b.x)-.4)/25);ix<=Math.floor((Math.max(segment.a.x,segment.b.x)+.4)/25);ix++)for(let iz=Math.floor((Math.min(segment.a.z,segment.b.z)-.4)/25);iz<=Math.floor((Math.max(segment.a.z,segment.b.z)+.4)/25);iz++){const key=ix+','+iz;if(!collision.has(key))collision.set(key,[]);collision.get(key).push({segment,id:c.id})}}}
 function removeChunk(id){const c=chunks.get(id);if(!c)return;if(c.mesh){scene.remove(c.mesh);c.mesh.dispose()}for(const[key,rows]of collision){const rest=rows.filter(r=>r.id!==id);if(rest.length)collision.set(key,rest);else collision.delete(key)}chunks.delete(id)}
 return{addChunk(id,buildings){if(chunks.has(id))return;const ring=buildings[0]?.rings[0];if(!ring)return;const p=facadeProfile(buildings[0]);chunks.set(id,{id,buildings,x:p.x,z:p.z,mesh:null})},removeChunk,update(camera){const now=performance.now();if(now>next){next=now+300;queue=[...chunks.values()].filter(c=>!c.mesh&&Math.hypot(camera.x-c.x,camera.z-c.z)<1200).sort((a,b)=>Math.hypot(camera.x-a.x,camera.z-a.z)-Math.hypot(camera.x-b.x,camera.z-b.z));for(const c of chunks.values())if(c.mesh){const s=c.mesh.boundingSphere,d=Math.max(0,Math.hypot(camera.x-s.center.x,camera.z-s.center.z)-s.radius);c.mesh.visible=d<600;c.mesh.count=d<150?c.mesh.instanceMatrix.count:c.panels}}const end=performance.now()+budgetMs;do{if(!job){const c=queue.shift();if(!c)return;if(c.mesh||chunks.get(c.id)!==c)continue;job={c,generator:build(c)}}const result=job.generator.next();if(result.done)job=null}while(performance.now()<end)},free(x,z){for(const{segment:s}of collision.get(Math.floor(x/25)+','+Math.floor(z/25))||[]){const dx=s.b.x-s.a.x,dz=s.b.z-s.a.z,t=T.MathUtils.clamp(((x-s.a.x)*dx+(z-s.a.z)*dz)/(dx*dx+dz*dz||1),0,1);if(Math.hypot(x-s.a.x-dx*t,z-s.a.z-dz*t)<.28)return false}return true},get stats(){return{chunks:[...chunks.values()].filter(c=>c.mesh).length}}};
}
